import{_ as s,C as r,o,c as i,a5 as d,E as l,j as a,a as n}from"./chunks/framework.BwlBv862.js";const q=JSON.parse('{"title":"按日期查看统计数据","description":"","frontmatter":{"title":"按日期查看统计数据","docId":"user.points.statistics","translationKey":"user.points.statistics","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"a7333d75baa9aec6e0c4afb69d1c773575a56ee8da982f0fa5a11a73b903ec2d","translationRevision":"65a78c17935897b77577b4ac2f50610122de509350e14d8f1e7addced9a13e84","order":20},"headers":[],"relativePath":"zh/user/points/statistics.md","filePath":"zh/user/points/statistics.md","lastUpdated":1794611623000}'),c={name:"zh/user/points/statistics.md"};function u(p,e,h,m,f,b){const t=r("DemoFrame");return o(),i("div",null,[e[0]||(e[0]=d('<h1 id="review-statistics-across-dates" tabindex="-1">按日期查看统计数据 <a class="header-anchor" href="#review-statistics-across-dates" aria-label="Permalink to &quot;按日期查看统计数据 {#review-statistics-across-dates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>在有用的日期范围内比较某位主播的活动，并理解统计总量为何与可见事件流或积分余额不同。你需要本地安装中已有记录，并通过 <a href="./../live/connections.html">连接</a> 选中目标主播。Cloud 登录不是这些本地分析的数据来源。</p><h2 id="query-the-recorded-period" tabindex="-1">查询已记录的时段 <a class="header-anchor" href="#query-the-recorded-period" aria-label="Permalink to &quot;查询已记录的时段 {#query-the-recorded-period}&quot;">​</a></h2><ol><li>打开 <strong>数据分析</strong>，确认日期控件旁的主播。所选主播决定查询哪些已保存的聚合数据。</li><li>选择 <strong>今天</strong>、<code>7d</code>、<code>30d</code>、<code>90d</code> 或自定义范围。使用自定义日期时，明确设置起止日期并检查先后顺序。</li><li>比较结果前，先阅读显示的日期跨度及会话数量。本地日期边界使用时区偏移；更改电脑时区可能改变时段的解释方式。</li><li>选择需要的指标：聊天、礼物、点赞、钻石或观众峰值。使用活动图表比较时段，在贡献者表格中查看返回的领先观众。</li><li>在贡献者表格中搜索已经返回的观众。这不是对所有历史观众进行无限制搜索。</li><li>新活动发生后或返回页面时，选择 <strong>刷新</strong>。分享任何数字时，一并记录主播、日期及指标。</li></ol><p>当前页面以主播和日期跨度调用原生 <code>analytics.summary</code> 操作，读取包含以往记录会话的持久化聚合数据，不局限于当前事件流保留的事件。统计数据库保存聚合数据，不保存聊天逐字记录。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>本地持久化分析及日期范围查询均可使用。没有活动的日期返回空结果是正常情况。积分余额可能不同，因为<a href="./rules.html">获取倍率</a>、手动调整与自动化奖励衡量的是其他内容。钻石、礼物数量和积分不能互换单位。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>数据看似缺失时，请清空贡献者搜索、扩大日期范围、确认主播并刷新。宿主错误后保留诊断代码，待连接恢复再重试。清空事件流不会擦除统计。新的数据目录没有先前历史；迁移安装时请使用<a href="./../preferences/backups.html">备份</a>。</p>',10)),l(t,{scenario:"analytics",locale:"zh",title:"演示：统计分析"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[n("运行细节 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "运行细节 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Analytics 当前请求所选主播及日期范围内的前 10 位贡献者。搜索仅筛选收到的子集，不是全局观众查询。这些持久聚合的时间范围与单位不同于动态流会话内的钻石/点赞榜单，也不同于积分余额。导出或比较结果时，请同时保留主播、日期和指标。",-1))])}const v=s(c,[["render",u]]);export{q as __pageData,v as default};
